import sys

def find_longest_repeating_substring(s):
    n = len(s)
    lcsuff = [[0 for _ in range(n+1)] for _ in range(n+1)]
    length = 0
    end_index = 0

    for i in range(1, n+1):
        for j in range(1, n+1):
            if s[i-1] == s[j-1] and i != j:
                lcsuff[i][j] = lcsuff[i-1][j-1] + 1
                if lcsuff[i][j] > length:
                    length = lcsuff[i][j]
                    end_index = i
            else:
                lcsuff[i][j] = 0

    return s[end_index-length:end_index]

def main():
    import sys
    t = sys.stdin.read().strip()

    if len(t) < 2:
        print("NO")
        return

    longest_substring = find_longest_repeating_substring(t)

    if longest_substring and len(longest_substring) > 0 and len(longest_substring) < len(t):
        candidate = t[:len(t) - len(longest_substring)]
        if candidate + longest_substring == t:
            print("YES")
            print(candidate)
            return

    print("NO")

if __name__ == "__main__":
    main()

