def find_possible_message(t):
    n = len(t)

    # Check for the simplest case where the string is composed of two identical parts
    if n % 2 == 0 and t[:n//2] == t[n//2:]:
        return "YES", t[:n//2]

    # Try to find a repeating pattern
    for i in range(1, n // 2 + 1):
        if n % i == 0:
            candidate = t[:i]
            repeated = candidate * (n // i)
            if repeated == t:
                return "YES", candidate

    # Check for overlapping patterns
    for i in range(1, n - 1):
        for j in range(1, n - i):
            if t.startswith(t[i:i+j]) and t.endswith(t[i:i+j]):
                candidate = t[:i+j]
                repeated = candidate + t[i+j:]
                if repeated == t:
                    return "YES", candidate

    return "NO", ""

